import type { ElectrobunConfig } from "electrobun"

// Desktop app: the main process (Bun) starts the same Zero server and opens a native window for it.
// `web/` is the apps/web build and `drizzle/` the database migrations, copied by prebuild (Electrobun only copies paths inside the project).
// Signing and notarization (macOS) turn on by themselves when the credentials are in the environment (CI secrets):
//   ELECTROBUN_DEVELOPER_ID, and ELECTROBUN_APPLEID + ELECTROBUN_APPLEIDPASS + ELECTROBUN_TEAMID.
// Icon: assets/icon.svg is the source; icon.iconset and assets/icon.png are generated by `bun run icons`.
const env = process.env
const sign = !!env.ELECTROBUN_DEVELOPER_ID
const notarize = sign && !!(env.ELECTROBUN_APPLEID && env.ELECTROBUN_APPLEIDPASS && env.ELECTROBUN_TEAMID)

export default {
  app: {
    name: "Zero",
    identifier: "dev.zero.app",
    version: "0.1.0"
  },
  build: {
    mainProcess: "bun",
    bun: { entrypoint: "src/bun/index.ts" },
    copy: { web: "web", drizzle: "drizzle" },
    mac: { icons: "icon.iconset", codesign: sign, notarize, createDmg: true },
    win: { icon: "assets/icon.png" },
    linux: { icon: "assets/icon.png" }
  },
  runtime: { exitOnLastWindowClosed: true }
} satisfies ElectrobunConfig
